"\n",
"/* Floating buttons */\n",
".fab { position: fixed; bottom: 24px; z-index: 50; width: 60px; height: 60px; border-radius: 999px; display: inline-flex; align-items: center; justify-content: center; border: 2px ",
"solid #111111; cursor: pointer; text-decoration: none; transition: opacity .2s, transform .2s; }\n",
".wa { right: 24px; width: 76px; height: 76px; background: #1DA851; color: #FFFFFF; }\n",
".wa.off { opacity: 0; transform: scale(.8); pointer-events: none; }\n",
".v4 .ax-fab { left: 24px; background: #111111; color: #FFFFFF; border-color: #FFFFFF; box-shadow: 0 0 0 2px #111111; }\n",
".ax-p { position: fixed; left: 24px; bottom: 96px; z-index: 60; width: 320px; max-width: calc(100% - 32px); background: #FFFFFF; color: #111111; border: 2px solid #111111; border-r",
"adius: 16px; padding: 18px; display: flex; flex-direction: column; gap: 12px; box-shadow: 0 20px 50px rgba(0, 0, 0, .18); font-size: 16px; line-height: 1.4; letter-spacing: 0; word",
"-spacing: 0; }\n",
".ax-tt { font-size: 18px; font-weight: 700; }\n",
".ax-l { font-size: 14px; font-weight: 600; margin-bottom: 6px; }\n",
".ax-opts { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }\n",
".ax-o { min-height: 44px; border-radius: 10px; border: 1.5px solid #111111; background: #FFFFFF; font-weight: 700; cursor: pointer; }\n",
".ax-o[aria-pressed=\"true\"] { background: #111111; color: #FFFFFF; }\n",
".ax-sw { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; padding: 0 4px; background: transparent; border: 0; border-top: 1px solid ",
"#E4E2D9; cursor: pointer; text-align: left; font-size: 16px; }\n",
".ax-sw i { flex: none; position: relative; width: 44px; height: 26px; border-radius: 999px; border: 2px solid #111111; background: #FFFFFF; transition: background .2s; }\n",
".ax-sw i::after { content: \"\"; position: absolute; top: 3px; left: 3px; width: 16px; height: 16px; border-radius: 999px; background: #111111; transition: transform .2s; }\n",
".ax-sw[aria-checked=\"true\"] i { background: #111111; }\n",
".ax-sw[aria-checked=\"true\"] i::after { background: #FFFFFF; transform: translateX(18px); }\n",
".ax-f { display: flex; gap: 8px; margin-top: 4px; }\n",
