".ax-f .ax-close { background: #111111; color: #FFFFFF; }\n",
"\n",
"/* High contrast */\n",
".v4[data-hc=\"true\"] { --bg: #FFFFFF; --mut: #000000; --line: #000000; --fg: #000000; }\n",
